```import { Denops } from "<https://deno.land/x/denops_std@v1.0.1/mod.ts>"
import * as fn from "<https://deno.land/x/denops_std@v1.0.1/function/mod.ts>"
import * as helper from "<https://deno.land/x/denops_std@v1.0.1/helper/mod.ts>"

export async function main(denops: Denops) {
  denops.dispatcher = ({
    async run(): Promise&lt;unknown&gt; {
      const name = await fn.input(denops, "&gt; ")
      console.log(name)
      return await Promise.resolve(name)
    }
  });
  await helper.execute(denops, `
    command! -nargs=0 DenopsSandbox echomsg denops#request("${denops.name}", "run", [])
  `);
}```
これで問題なく動くんですけどね（汎用sandbox用repoなので色々と雑）

